function boolSc(v){return v===true||v==='yes'||v===1||v==='true';}
function cleanIm(im){if(!im)return '';if(/vary|varies|manufactur|imprint|note:|by strength|film|debossed|often|e\.g\.|also/i.test(im))return '';return im.slice(0,10);}
function cleanSrc(a){var ok=/drugs\.com|dailymed\.nlm\.nih\.gov|medlineplus\.gov|fda\.gov/;var out=(a||[]).filter(function(u){return ok.test(u);});return out.length?out:(a||[]).slice(0,1);}
const all=[].concat.apply([],B).map(function(d){
  var pills=Array.isArray(d.pills)?d.pills:[];
  if(!pills.length||typeof pills[0]!=='object'){pills=[{f:'tablet',s:'see label'}];}
  pills=pills.map(function(p){var q=Object.assign({},p);if('sc'in q)q.sc=boolSc(q.sc);if('im'in q)q.im=cleanIm(q.im);if(q.s&&/note:/i.test(q.s))q.s=q.s.split(/note:/i)[0].trim().replace(/[;,]$/,'');return q;});
  return Object.assign({},d,{pills:pills,src:cleanSrc(d.src)});
});
